UPDATE market_question SET status = #{to}, version = version + 1, updated_at = #{now}
  , listed_by = #{listedBy}, submitted_for_listing = 0
  , cancel_reason = #{cancelReason}
  , void_reason = #{voidReason}
  , ended_at = #{now}
WHERE id = #{id} AND status = #{from} AND deleted_at IS NULL

UPDATE market_question SET winning_option_id = #{winningOptionId}, actual_start_at = #{actualStartAt}, resolved_by = #{resolvedBy},
  version = version + 1, updated_at = #{now}
WHERE id = #{id} AND settle_phase = 'NONE' AND deleted_at IS NULL

UPDATE market_question SET winning_option_id = #{winningOptionId}, actual_start_at = #{actualStartAt}, resolved_by = #{resolvedBy},
  dispute_deadline_at = #{deadline}, version = version + 1, updated_at = #{now}
WHERE id = #{id} AND status = 'PUBLICIZING' AND settle_phase = 'NONE' AND deleted_at IS NULL

