mapper.select:
SELECT FROM market_question
ORDER BY id DESC ORDER BY close_at, id
LIMIT #{offset}, #{limit}

SELECT  FROM market_question
WHERE today_slate = 1 AND status <> 'DRAFT' AND deleted_at IS NULL AND event_start_at >= #{from} AND event_start_at < #{to}
ORDER BY event_start_at, id LIMIT #{limit}

SELECT  FROM market_question
WHERE today_slate = 1 AND status IN ('LISTED', 'PAUSED') AND deleted_at IS NULL AND event_start_at >= #{from}
ORDER BY event_start_at, id LIMIT 1

mapper.sql:
WHERE deleted_at IS NULL AND ended_at IS NOT NULL AND status IN #{s}
AND category = #{category}
AND ended_at >= #{from}
AND ended_at < #{to}
